using System.ComponentModel.DataAnnotations;
namespace Erp.Modules.Purchasing.Pages; public sealed class PurchaseOrderForm { [Required] public string? SupplierId { get; set; } [Required, StringLength(3, MinimumLength = 3)] public string CurrencyCode { get; set; } = "USD"; public DateOnly OrderDate { get; set; } = DateOnly.FromDateTime(DateTime.UtcNow); public DateOnly? ExpectedDeliveryDate { get; set; } [StringLength(4000)] public string? Notes { get; set; } public string? ConcurrencyStamp { get; set; } public List<PurchaseOrderLineForm> Lines { get; set; } = [new()]; public PurchaseOrderRequest ToRequest() => new(Guid.TryParse(SupplierId, out var supplier) ? supplier : Guid.Empty, CurrencyCode, OrderDate, ExpectedDeliveryDate, Notes, Lines.Select(x => x.ToRequest()).ToList(), ConcurrencyStamp); public static PurchaseOrderForm From(PurchaseOrderDto x) => new() { SupplierId = x.SupplierId.ToString(), CurrencyCode = x.CurrencyCode, OrderDate = x.OrderDate, ExpectedDeliveryDate = x.ExpectedDeliveryDate, Notes = x.Notes, ConcurrencyStamp = x.ConcurrencyStamp, Lines = x.Lines.Select(l => new PurchaseOrderLineForm { ProductId = l.ProductId.ToString(), Quantity = l.Quantity, UnitPrice = l.UnitPrice, DiscountPercent = l.DiscountPercent, TaxPercent = l.TaxPercent, Description = l.Description }).ToList() }; } public sealed class PurchaseOrderLineForm { [Required] public string? ProductId { get; set; } [Range(typeof(decimal), "0.0001", "999999999")] public decimal Quantity { get; set; } = 1; [Range(typeof(decimal), "0", "999999999")] public decimal? UnitPrice { get; set; } [Range(typeof(decimal), "0", "100")] public decimal DiscountPercent { get; set; } [Range(typeof(decimal), "0", "100")] public decimal TaxPercent { get; set; } [StringLength(500)] public string? Description { get; set; } public PurchaseOrderLineRequest ToRequest() => new(Guid.TryParse(ProductId, out var id) ? id : Guid.Empty, Quantity, UnitPrice, DiscountPercent, TaxPercent, Description); }
